package com.minecolonies.api.colony;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.StringTag;
import org.jetbrains.annotations.Nullable;

/**
 * Container for all the grave data
 */
public class GraveData implements IGraveData
{
    /**
     * NBTTag to store the last grave owner.
     */
    private static final String TAG_CITIZEN_NBT = "citizennbt";

    /**
     * NBTTag to store the name of the last grave owner name.
     */
    private static final String TAG_CITIZEN_NAME = "citizenname";

    /**
     * NBTTag to store the name of the last grave owner job name.
     */
    private static final String TAG_CITIZEN_JOB_NAME = "citizenjobname";

    /**
     * The data NBT of the citizen .
     */
    @Nullable
    private CompoundTag citizenDataNBT = null;

    /**
     * The name of the citizen.
     */
    @Nullable
    private String citizenName = null;

    /**
     * The name of the job of the citizen
     */
    @Nullable
    private String citizenJobName = null;

    /**
     * get the data NBT of the citizen .
     */
    @Nullable
    public CompoundTag getCitizenDataNBT()
    {
        return citizenDataNBT;
    }

    /**
     * Set data NBT of the citizen .
     */
    public void setCitizenDataNBT(@Nullable final CompoundTag citizenDataNBT)
    {
        this.citizenDataNBT = citizenDataNBT;
    }

    /**
     * Get the name of the citizen.
     */
    @Nullable
    public String getCitizenName()
    {
        return citizenName;
    }

    /**
     * Set the name of the citizen.
     */
    public void setCitizenName(@Nullable final String citizenName)
    {
        this.citizenName = citizenName;
    }

    /**
     * Get the name of the job of the citizen
     */
    @Nullable
    public String getCitizenJobName()
    {
        return citizenJobName;
    }

    /**
     * Set the name of the job of the citizen
     */
    public void setCitizenJobName(@Nullable final String citizenJobName)
    {
        this.citizenJobName = citizenJobName;
    }

    @Override
    public void read(CompoundTag compound)
    {
        citizenDataNBT  = compound.contains(TAG_CITIZEN_NBT) ? compound.getCompound(TAG_CITIZEN_NBT) : null;
        citizenName     = compound.contains(TAG_CITIZEN_NAME) ? compound.getString(TAG_CITIZEN_NAME) : null;
        citizenJobName  = compound.contains(TAG_CITIZEN_JOB_NAME) ? compound.getString(TAG_CITIZEN_JOB_NAME) : null;
    }

    @Override
    public CompoundTag write()
    {
        final CompoundTag compound = new CompoundTag();
        if (citizenDataNBT != null) { compound.put(TAG_CITIZEN_NBT, citizenDataNBT); }
        if (citizenName != null)    { compound.put(TAG_CITIZEN_NAME, StringTag.valueOf(citizenName)); }
        if (citizenJobName != null) { compound.put(TAG_CITIZEN_JOB_NAME,StringTag.valueOf(citizenJobName)); }

        return compound;
    }
}

package com.minecolonies.api.colony.managers.interfaces;

import com.minecolonies.api.colony.ICitizenData;
import com.minecolonies.api.entity.citizen.happiness.IHappinessModifier;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.level.Level;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.List;

/**
 * The interface of the citizen manager.
 */
public interface ICitizenManager extends IEntityManager
{

    /**
     * Spawn a brand new Citizen.
     */
    void spawnOrCreateCitizen();

    /**
     * Spawn a citizen with specific citizen data.
     *
     * @param data  Data to use to spawn citizen.
     * @param world the world to spawn it in.
     * @return the citizen data of the spawned citizen.
     */
    default ICitizenData spawnOrCreateCitizen(final ICitizenData data, @NotNull final Level world)
    {
        return this.spawnOrCreateCivilian(data, world, null, false);
    }

    /**
     * Spawn a citizen with specific citizen data.
     *
     * @param data     Data to use to spawn citizen.
     * @param world    the world to spawn it in.
     * @param spawnPos the Blockposition to spawn at
     * @return the new citizen.
     */
    default ICitizenData spawnOrCreateCitizen(final ICitizenData data, @NotNull final Level world, final BlockPos spawnPos)
    {
        return this.spawnOrCreateCivilian(data, world, List.of(spawnPos), false);
    }

    /**
     * Get the first unemployed citizen.
     *
     * @return Citizen with no current job.
     */
    @Nullable
    ICitizenData getJoblessCitizen();

    /**
     * Recalculates how many citizen can be in the colony.
     */
    void calculateMaxCitizens();

    @Override
    ICitizenData createAndRegisterCivilianData();

    /**
     * Resurrect a citizen from its saved NBT.
     *
     * @param compoundNBT the saved citizen NBT
     * @param resetId if true, will calculate a new citizen ID
     * @param world
     * @param spawnPos position where to resurrect the citizen
     * @return the citizenData of the resurrected citizen
     */
    ICitizenData resurrectCivilianData(@NotNull final CompoundTag compoundNBT, final boolean resetId, @NotNull final Level world, final BlockPos spawnPos);

    /**
     * Get all citizens.
     *
     * @return a copy of the list of citizens.
     */
    List<ICitizenData> getCitizens();

    /**
     * Get max citizens of the colony.
     *
     * @return the amount.
     */
    int getMaxCitizens();

    /**
     * Get potential max citizens of the colony. The potential considers all available beds including not assigned guard towers.
     *
     * @return the amount.
     */
    int getPotentialMaxCitizens();

    /**
     * Get the max citizens based on the research.
     *
     * @return the max.
     */
    double maxCitizensFromResearch();

    /**
     * Get the current amount of citizens, might be bigger then {@link #getMaxCitizens()}
     *
     * @return The current amount of citizens in the colony.
     */
    int getCurrentCitizenCount();

    /**
     * Set the new max citizens.
     *
     * @param newMaxCitizens the amount to set.
     */
    void setMaxCitizens(final int newMaxCitizens);

    /**
     * Set the new potential max citizens. The potential considers all available beds including not assigned guard towers.
     *
     * @param newMaxCitizens the potential amount to set.
     */
    void setPotentialMaxCitizens(final int newMaxCitizens);

    /**
     * Check for the citizen happiness and update the colony happiness with it.
     */
    void checkCitizensForHappiness();

    /**
     * Tick the citizen data of all active citizens.
     */
    boolean tickCitizenData(int tickRate);

    /**
     * Call this to set all the citizens in the colony to mourn or not.
     *
     * @param mourn boolean to indicate if citizen should mourn or not
     */
    void updateCitizenMourn(final ICitizenData data, final boolean mourn);

    /**
     * Call this to set all citizens asleep
     *
     * @param sleep boolean to indicate whether the citizens are all asleep
     */
    void updateCitizenSleep(final boolean sleep);

    /**
     * Get a random citizen.
     *
     * @return the random citizen.
     */
    ICitizenData getRandomCitizen();

    /**
     * Inject a modifier into all citizens
     *
     * @param modifier the modifier.
     */
    void injectModifier(final IHappinessModifier modifier);

    /**
     * Call this when citizens sleep
     */
    void onCitizenSleep();

    @Override
    ICitizenData getCivilian(final int citizenId);

    /**
     * Called in the morning.
     */
    void onWakeUp();

    /**
     * Post building load actions
     */
    void afterBuildingLoad();

    /**
     * Called when flag is changed
     */
    void onFlagChange();
}

package com.minecolonies.api.colony.permissions;

import com.minecolonies.api.util.Utils;

import java.util.Objects;

public class Rank
{
    /**
     * The name of the rank
     */
    private String name;
    /**
     * The id of the rank
     */
    private int id;
    /**
     * Whether the rank is one of the initial ranks which cannot be deleted
     */
    private boolean isInitial;

    /**
     * Whether the rank is a colony manager (can perform certain actions)
     */
    private boolean isColonyManager;

    /**
     * Whether the rank is hostile (can attack and be attacked)
     */
    private boolean isHostile;

    /**
     * Holds all bits indicating given permissions
     */
    private long permissionData = 0;

    /**
     * Rank constructor
     *
     * @param id           the id of the rank
     * @param name         the name of the rank
     * @param isInitial    whether the rank is an initial rank
     */
    public Rank(int id, long permissionData, String name, boolean isInitial, boolean isColonyManager, boolean isHostile)
    {
        this.id = id;
        this.permissionData = permissionData;
        this.name = name;
        this.isInitial = isInitial;
        this.isColonyManager = isColonyManager;
        this.isHostile = isHostile;
    }

    public Rank(int id, String name, boolean isInitial)
    {
        this(id, 0L, name, isInitial, false, false);
    }

    /**
     * Get the id of the rank
     * @return the id
     */
    public int getId()
    {
        return id;
    }

    /**
     * Get the name of the rank
     * @return the name
     */
    public String getName()
    {
        return name;
    }

    /**
     * Get whether this ranks is an initial rank which cannot be deleted
     * @return true if so
     */
    public boolean isInitial() { return isInitial; }

    /**
     * Get whether this rank is a colony manager
     * @return true if so
     */
    public boolean isColonyManager() { return isColonyManager; }

    /**
     * Get whether this rank is hostile
     * @return true if so
     */
    public boolean isHostile() { return isHostile; }

    /**
     * Set whether this rank is a colony manager
     * @param isColonyManager whether the rank is a colony manager
     */
    public void setColonyManager(boolean isColonyManager)
    {
        this.isColonyManager = isColonyManager;
    }

    /**
     * Set whether this rank is hostile
     * @param isHostile whether the rank is hostile
     */
    public void setHostile(boolean isHostile)
    {
        this.isHostile = isHostile;
    }

    @Override
    public boolean equals(final Object o)
    {
        if (this == o)
        {
            return true;
        }
        if (o == null || getClass() != o.getClass())
        {
            return false;
        }
        final Rank rank = (Rank) o;
        return id == rank.id && name.equals(rank.name);
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(name, id);
    }

    public int compareTo(Rank rank)
    {
        return this.getId() - rank.getId();
    }

    /**
     * Adds the given action permission if it is not set yet
     *
     * @param action
     * @return
     */
    public boolean addPermission(final Action action)
    {
        if (!Utils.testFlag(permissionData, action.getFlag()))
        {
            permissionData = Utils.setFlag(permissionData, action.getFlag());
            return true;
        }

        return false;
    }

    /**
     * Adds the given action permission if it is not set yet
     *
     * @param action
     * @return
     */
    public boolean removePermission(final Action action)
    {
        if (Utils.testFlag(permissionData, action.getFlag()))
        {
            permissionData = Utils.unsetFlag(permissionData, action.getFlag());
            return true;
        }

        return false;
    }

    public long getPermissions()
    {
        return permissionData;
    }
}

package com.minecolonies.api.inventory.container;

import com.minecolonies.api.inventory.ModContainers;
import com.minecolonies.api.tileentities.AbstractTileEntityGrave;
import com.minecolonies.api.util.ItemStackUtils;
import net.minecraft.core.BlockPos;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.inventory.Slot;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.items.IItemHandler;
import net.minecraftforge.items.SlotItemHandler;
import org.jetbrains.annotations.NotNull;

import static com.minecolonies.api.util.constant.InventoryConstants.*;

/**
 * The container class for the grave.
 */
public class ContainerGrave extends AbstractContainerMenu
{
    /**
     * The inventory.
     */
    private final IItemHandler inventory;

    /**
     * The tileEntity.
     */
    public final AbstractTileEntityGrave grave;

    /**
     * Amount of rows.
     */
    private final int inventorySize;

    /**
     * Deserialize packet buffer to container instance.
     *
     * @param windowId     the id of the window.
     * @param inv          the player inventory.
     * @param packetBuffer network buffer
     * @return new instance
     */
    public static ContainerGrave fromFriendlyByteBuf(final int windowId, final Inventory inv, final FriendlyByteBuf packetBuffer)
    {
        return new ContainerGrave(windowId, inv, packetBuffer);
    }

    /**
     * The container constructor.
     *
     * @param windowId the window id.
     * @param inv      the inventory.
     * @param extra    some extra data.
     */
    public ContainerGrave(final int windowId, final Inventory inv, final FriendlyByteBuf extra)
    {
        super(ModContainers.graveInv.get(), windowId);
        final BlockPos grave = extra.readBlockPos();

        final AbstractTileEntityGrave abstractTileEntityGrave = (AbstractTileEntityGrave) inv.player.level().getBlockEntity(grave);
        this.inventory = abstractTileEntityGrave.getInventory();

        this.grave = abstractTileEntityGrave;
        this.inventorySize = this.inventory.getSlots() / INVENTORY_COLUMNS;
        final int size = this.inventory.getSlots();

        final int columns = inventorySize <= INVENTORY_BAR_SIZE ? INVENTORY_COLUMNS : ((size / INVENTORY_BAR_SIZE) + 1);
        final int extraOffset = inventorySize <= INVENTORY_BAR_SIZE ? 0 : 2;
        int index = 0;

        for (int j = 0; j < Math.min(this.inventorySize, INVENTORY_BAR_SIZE); ++j)
        {
            for (int k = 0; k < columns; ++k)
            {
                if (index < size)
                {
                    this.addSlot(
                      new SlotItemHandler(inventory, index,
                        INVENTORY_BAR_SIZE + k * PLAYER_INVENTORY_OFFSET_EACH,
                        PLAYER_INVENTORY_OFFSET_EACH + j * PLAYER_INVENTORY_OFFSET_EACH));
                    index++;
                }
            }
        }

        // Player inventory slots
        // Note: The slot numbers are within the player inventory and may be the same as the field inventory.
        int i;
        for (i = 0; i < INVENTORY_ROWS; i++)
        {
            for (int j = 0; j < INVENTORY_COLUMNS; j++)
            {
                addSlot(new Slot(
                  inv,
                  j + i * INVENTORY_COLUMNS + INVENTORY_COLUMNS,
                  PLAYER_INVENTORY_INITIAL_X_OFFSET + j * PLAYER_INVENTORY_OFFSET_EACH,
                  PLAYER_INVENTORY_INITIAL_Y_OFFSET + extraOffset + PLAYER_INVENTORY_OFFSET_EACH * Math.min(this.inventorySize, INVENTORY_BAR_SIZE)
                    + i * PLAYER_INVENTORY_OFFSET_EACH
                ));
            }
        }

        for (i = 0; i < INVENTORY_COLUMNS; i++)
        {
            addSlot(new Slot(
              inv, i,
              PLAYER_INVENTORY_INITIAL_X_OFFSET + i * PLAYER_INVENTORY_OFFSET_EACH,
              PLAYER_INVENTORY_HOTBAR_OFFSET + extraOffset + PLAYER_INVENTORY_OFFSET_EACH * Math.min(this.inventorySize,
                INVENTORY_BAR_SIZE)
            ));
        }
    }

    @NotNull
    @Override
    public ItemStack quickMoveStack(final Player playerIn, final int index)
    {
        final Slot slot = this.slots.get(index);

        if (slot == null || !slot.hasItem())
        {
            return ItemStackUtils.EMPTY;
        }

        final ItemStack stackCopy = slot.getItem().copy();

        final int maxIndex = this.inventorySize * INVENTORY_COLUMNS;

        if (index < maxIndex)
        {
            if (!this.moveItemStackTo(stackCopy, maxIndex, this.slots.size(), true))
            {
                return ItemStackUtils.EMPTY;
            }
        }
        else if (!this.moveItemStackTo(stackCopy, 0, maxIndex, false))
        {
            return ItemStackUtils.EMPTY;
        }

        if (ItemStackUtils.getSize(stackCopy) == 0)
        {
            slot.set(ItemStackUtils.EMPTY);
        }
        else
        {
            slot.set(stackCopy);
            slot.setChanged();
        }

        return stackCopy;
    }

    @Override
    protected boolean moveItemStackTo(final ItemStack stack, final int startIndex, final int endIndex, final boolean reverseDirection)
    {
        final ItemStack before = stack.copy();
        final boolean merge =  super.moveItemStackTo(stack, startIndex, endIndex, reverseDirection);
        return merge;
    }

    @Override
    public boolean stillValid(final Player playerIn)
    {
        return true;
    }
}

package com.minecolonies.api.tileentities;

import com.minecolonies.api.colony.IGraveData;
import com.minecolonies.core.tileentities.TileEntityRack;
import net.minecraft.core.BlockPos;
import net.minecraft.world.MenuProvider;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import org.jetbrains.annotations.Nullable;

import static com.minecolonies.api.util.constant.Constants.DEFAULT_SIZE;
import static com.minecolonies.api.util.constant.Constants.TICKS_SECOND;

/**
 * Abstract class for minecolonies graves.
 */
public abstract class AbstractTileEntityGrave extends TileEntityRack implements MenuProvider
{
    /**
     * default duration of the countdown before the grave disapear, in ticks (20 ticks / seconds)
     */
    protected static final int DEFAULT_DECAY_TIMER = TICKS_SECOND * 60 * 10;

    /**
     * Is this grave decayed or not
     */
    protected boolean decayed;

    /**
     * The decay timer counting down before the grave decay and then disapear
     */
    protected int decay_timer;

    /**
     * The GraveData of the citizen that spawned this grave.
     */
    @Nullable
    protected IGraveData graveData;

    public AbstractTileEntityGrave(final BlockEntityType<? extends AbstractTileEntityGrave> tileEntityTypeIn, final BlockPos pos, final BlockState state)
    {
        super(tileEntityTypeIn, pos, state, DEFAULT_SIZE * 2);
        decay_timer = DEFAULT_DECAY_TIMER;
        decayed = false;
    }

    /**
     * Delay the decay timer by minutes
     * @param minutes number of minutes to delay the time by
     */
    public void delayDecayTimer(final double minutes)
    {
        decay_timer += minutes * TICKS_SECOND * 60;
    }

    /**
     * Get the graveData of the saved citizen
     */
    public IGraveData getGraveData()
    {
        return graveData;
    }

    /**
     * Set the graveData of the saved citizen
     * @param graveData
     */
    public void setGraveData(IGraveData graveData)
    {
        this.graveData = graveData;
        setChanged();
    }
}

package com.minecolonies.core.client.gui.townhall;

import com.ldtteam.blockui.Pane;
import com.ldtteam.blockui.PaneBuilders;
import com.ldtteam.blockui.controls.*;
import com.ldtteam.blockui.views.DropDownList;
import com.ldtteam.blockui.views.ScrollingList;
import com.minecolonies.api.MinecoloniesAPIProxy;
import com.minecolonies.api.colony.ICitizenDataView;
import com.minecolonies.api.colony.buildings.views.IBuildingView;
import com.minecolonies.api.util.Tuple;
import com.minecolonies.api.util.constant.CitizenConstants;
import com.minecolonies.core.MineColonies;
import com.minecolonies.core.colony.buildings.moduleviews.CombinedHiringLimitModuleView;
import com.minecolonies.core.colony.buildings.moduleviews.WorkerBuildingModuleView;
import com.minecolonies.core.colony.buildings.views.AbstractBuildingView;
import com.minecolonies.core.colony.buildings.workerbuildings.BuildingTownHall;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import org.jetbrains.annotations.NotNull;

import java.util.*;

import static com.minecolonies.api.research.util.ResearchConstants.CITIZEN_CAP;
import static com.minecolonies.api.util.constant.TranslationConstants.*;
import static com.minecolonies.api.util.constant.TranslationConstants.COM_MINECOLONIES_COREMOD_GUI_TOWNHALL_POPULATION_CHILDS;
import static com.minecolonies.api.util.constant.WindowConstants.*;

/**
 * BOWindow for the town hall.
 */
public class WindowStatsPage extends AbstractWindowTownHall
{
    /**
     * Map of intervals.
     */
    public static final LinkedHashMap<String, Integer> INTERVAL = new LinkedHashMap<>();

    static
    {
        INTERVAL.put("com.minecolonies.coremod.gui.interval.yesterday", 1);
        INTERVAL.put("com.minecolonies.coremod.gui.interval.lastweek", 7);
        INTERVAL.put("com.minecolonies.coremod.gui.interval.100days", 100);
        INTERVAL.put("com.minecolonies.coremod.gui.interval.alltime", -1);
    }

    /**
     * Drop down list for interval.
     */
    private DropDownList intervalDropdown;

    /**
     * Current selected interval.
     */
    public String selectedInterval = "com.minecolonies.coremod.gui.interval.yesterday";

    /**
     * Constructor for the town hall window.
     *
     * @param townHall {@link BuildingTownHall.View}.
     */
    public WindowStatsPage(final BuildingTownHall.View townHall)
    {
        super(townHall, "layoutstats.xml");
    }

    /**
     * Executed when <code>WindowTownHall</code> is opened. Does tasks like setting buttons.
     */
    @Override
    public void onOpened()
    {
        super.onOpened();
        updateStats();
        createAndSetStatistics();
    }

    /**
     *
     * Creates several statistics and sets them in the building GUI.
     */
    private void createAndSetStatistics()
    {
        final int citizensSize = buildingView.getColony().getCitizens().size();
        final int citizensCap;

        if (MinecoloniesAPIProxy.getInstance().getGlobalResearchTree().hasResearchEffect(CITIZEN_CAP))
        {
            final int max = Math.max(CitizenConstants.CITIZEN_LIMIT_DEFAULT, (int) this.buildingView.getColony().getResearchManager().getResearchEffects().getEffectStrength(CITIZEN_CAP));
            citizensCap = Math.min(max, MineColonies.getConfig().getServer().maxCitizenPerColony.get());
        }
        else
        {
            citizensCap = MineColonies.getConfig().getServer().maxCitizenPerColony.get();
        }

        final Text totalCitizenLabel = findPaneOfTypeByID(TOTAL_CITIZENS_LABEL, Text.class);
        totalCitizenLabel.setText(Component.translatable(COM_MINECOLONIES_COREMOD_GUI_TOWNHALL_POPULATION_TOTALCITIZENS_COUNT,
          citizensSize,
          Math.max(citizensSize, buildingView.getColony().getCitizenCountLimit())));
        List<MutableComponent> hoverText = new ArrayList<>();
        if(citizensSize < (citizensCap * 0.9) && citizensSize < (buildingView.getColony().getCitizenCountLimit() * 0.9))
        {
            totalCitizenLabel.setColors(DARKGREEN);
        }
        else if(citizensSize < citizensCap)
        {
            hoverText.add(Component.translatable(WARNING_POPULATION_NEEDS_HOUSING, this.buildingView.getColony().getName()));
            totalCitizenLabel.setColors(ORANGE);
        }
        else
        {
            if(citizensCap < MineColonies.getConfig().getServer().maxCitizenPerColony.get())
            {
                hoverText.add(Component.translatable(WARNING_POPULATION_RESEARCH_LIMITED, this.buildingView.getColony().getName()));
            }
            else
            {
                hoverText.add(Component.translatable( WARNING_POPULATION_CONFIG_LIMITED, this.buildingView.getColony().getName()));
            }
            totalCitizenLabel.setText(Component.translatable(COM_MINECOLONIES_COREMOD_GUI_TOWNHALL_POPULATION_TOTALCITIZENS_COUNT, citizensSize, citizensCap));
            totalCitizenLabel.setColors(RED);
        }
        PaneBuilders.tooltipBuilder().hoverPane(totalCitizenLabel).build().setText(hoverText);

        int children = 0;
        final Map<String, Tuple<Integer, Integer>> jobMaxCountMap = new HashMap<>();
        for (@NotNull final IBuildingView building : buildingView.getColony().getClientBuildingManager().getBuildings().values())
        {
            if (building instanceof AbstractBuildingView)
            {
                for (final WorkerBuildingModuleView module : building.getModuleViews(WorkerBuildingModuleView.class))
                {
                    int alreadyAssigned = -1;
                    if (module instanceof CombinedHiringLimitModuleView)
                    {
                        alreadyAssigned = 0;
                        for (final WorkerBuildingModuleView combinedModule : building.getModuleViews(WorkerBuildingModuleView.class))
                        {
                            alreadyAssigned += combinedModule.getAssignedCitizens().size();
                        }
                    }
                    int max = module.getMaxInhabitants();
                    if (alreadyAssigned != -1)
                    {
                        max -= alreadyAssigned;
                        max += module.getAssignedCitizens().size();
                    }
                    int workers = module.getAssignedCitizens().size();

                    final String jobName = module.getJobDisplayName().toLowerCase(Locale.US);

                    final Tuple<Integer, Integer> tuple = jobMaxCountMap.getOrDefault(jobName, new Tuple<>(0, 0));
                    jobMaxCountMap.put(jobName, new Tuple<>(tuple.getA() + workers, tuple.getB() + max));
                }
            }
        }

        //calculate number of children
        int unemployed = 0;
        for (ICitizenDataView iCitizenDataView : buildingView.getColony().getCitizens().values())
        {
            if (iCitizenDataView.isChild())
            {
                children++;
            }
            else if (iCitizenDataView.getJobView() == null)
            {
                unemployed++;
            }
        }

        final int childCount = children;
        final int unemployedCount = unemployed;

        final ScrollingList list = findPaneOfTypeByID("citizen-stats", ScrollingList.class);
        if (list == null)
        {
            return;
        }

        final int maxJobs = jobMaxCountMap.size();
        final List<Map.Entry<String, Tuple<Integer, Integer>>> theList = new ArrayList<>(jobMaxCountMap.entrySet());
        theList.sort(Map.Entry.comparingByKey());

        list.setDataProvider(new ScrollingList.DataProvider()
        {
            @Override
            public int getElementCount()
            {
                return maxJobs + 2;
            }

            @Override
            public void updateElement(final int index, @NotNull final Pane rowPane)
            {
                final Text label = rowPane.findPaneOfTypeByID(CITIZENS_AMOUNT_LABEL, Text.class);
                // preJobsHeaders = number of all unemployed citizens

                if (index < theList.size())
                {
                    final Map.Entry<String, Tuple<Integer, Integer>> entry = theList.get(index);
                    final String jobString = Component.translatable(entry.getKey()).getString();
                    final String formattedJobString = jobString.substring(0, 1).toUpperCase(Locale.US) + jobString.substring(1);

                    final Component numberOfWorkers = Component.translatable(COM_MINECOLONIES_COREMOD_GUI_TOWNHALL_POPULATION_EACH, formattedJobString, entry.getValue().getA(), entry.getValue().getB());
                    label.setText(numberOfWorkers);
                }
                else
                {
                    if (index == maxJobs + 1)
                    {
                        label.setText(Component.translatable(COM_MINECOLONIES_COREMOD_GUI_TOWNHALL_POPULATION_UNEMPLOYED, unemployedCount));
                    }
                    else
                    {
                        label.setText(Component.translatable(COM_MINECOLONIES_COREMOD_GUI_TOWNHALL_POPULATION_CHILDS, childCount));
                    }
                }
            }
        });
    }

    /**
     * Update the display for the stats.
     */
    private void updateStats()
    {
        final @NotNull List<String> stats = new ArrayList<>(buildingView.getColony().getStatisticsManager().getStatTypes());

        findPaneOfTypeByID("stats", ScrollingList.class).setDataProvider(new ScrollingList.DataProvider()
        {
            /**
             * The number of rows of the list.
             * @return the number.
             */
            @Override
            public int getElementCount()
            {
                return stats.size();
            }

            /**
             * Inserts the elements into each row.
             * @param index the index of the row/list element.
             * @param rowPane the parent Pane for the row, containing the elements to update.
             */
            @Override
            public void updateElement(final int index, @NotNull final Pane rowPane)
            {
                int stat = buildingView.getColony().getStatisticsManager().getStatTotal(stats.get(index));
                int interval = INTERVAL.get(selectedInterval);
                if (interval > 0)
                {
                    stat = buildingView.getColony().getStatisticsManager().getStatsInPeriod(stats.get(index), buildingView.getColony().getDay() - interval, buildingView.getColony().getDay());
                }

                final Text resourceLabel = rowPane.findPaneOfTypeByID("desc", Text.class);
                resourceLabel.setText(Component.translatable(PARTIAL_STATS_MODIFIER_NAME + stats.get(index), stat));
            }
        });

        intervalDropdown = findPaneOfTypeByID(DROPDOWN_INTERVAL_ID, DropDownList.class);
        intervalDropdown.setHandler(this::onDropDownListChanged);

        intervalDropdown.setDataProvider(new DropDownList.DataProvider()
        {
            @Override
            public int getElementCount()
            {
                return INTERVAL.size();
            }

            @Override
            public String getLabel(final int index)
            {
                return Component.translatable((String) INTERVAL.keySet().toArray()[index]).getString();
            }
        });
        intervalDropdown.setSelectedIndex(new ArrayList<>(INTERVAL.keySet()).indexOf(selectedInterval));
    }

    private void onDropDownListChanged(final DropDownList dropDownList)
    {
        final String temp = (String) INTERVAL.keySet().toArray()[dropDownList.getSelectedIndex()];
        if (!temp.equals(selectedInterval))
        {
            selectedInterval = temp;
            updateStats();
        }
    }

    @Override
    protected String getWindowId()
    {
        return BUTTON_STATS;
    }
}

