public class CitizenManager implements ICitizenManager
{
    /**
     * Map of citizens with ID,CitizenData
     */
    @NotNull
    private final Map<Integer, ICitizenData> citizens = new HashMap<>();

    /**
     * Variables to determine if citizens have to be updated on the client side.
     */
    private boolean isCitizensDirty = false;

    /**
     * The highest citizen id.
     */
    private int topCitizenId = 0;

    /**
     * Max citizens without housing.
     */
    private int maxCitizens = 0;

    /**
     * Max citizens considering the spot in the empty guard tower.
     */
    private int potentialMaxCitizens;

    /**
     * The colony of the manager.
     */
    private final Colony colony;

    /**
     * The initial citizen spawn interval
     */
    private int respawnInterval = 30 * TICKS_SECOND;

    /**
     * The citizen spawn interval
     */
    private int citizenRespawnTimer = 5 * 60 * TICKS_SECOND;

    /**
     * Random obj.
     */
    private Random random = new Random();

    /**
     * Whether all citizens excluding guards are sleeping
     */
    private boolean areCitizensSleeping;

    /**
     * Creates the Citizenmanager for a colony.
     *
     * @param colony the colony.
     */
    public CitizenManager(final Colony colony)
    {
        this.colony = colony;
    }

    @Override
    public void registerCivilian(final AbstractCivilianEntity entity)
    {
        if (entity.getCivilianID() == 0 || citizens.get(entity.getCivilianID()) == null)
        {
            if (!entity.isAddedToWorld())
            {
                Log.getLogger().warn("Discarding entity not added to world, should be only called after:", new Exception());
            }
            entity.remove(Entity.RemovalReason.DISCARDED);
            return;
        }

        final ICitizenData data = citizens.get(entity.getCivilianID());

        if (data == null || !entity.getUUID().equals(data.getUUID()))
        {
            if (!entity.isAddedToWorld())
            {
                Log.getLogger().warn("Discarding entity not added to world, should be only called after:", new Exception());
            }
            entity.remove(Entity.RemovalReason.DISCARDED);
            return;
        }

        final Optional<AbstractEntityCitizen> existingCitizen = data.getEntity();

        if (existingCitizen.isEmpty())
        {
            data.setEntity(entity);
            return;
        }

        if (!entity.isAddedToWorld())
        {
            Log.getLogger().warn("Discarding entity not added to world, should be only called after:", new Exception());
        }
        entity.remove(Entity.RemovalReason.DISCARDED);
    }

    @Override
    public void unregisterCivilian(final AbstractCivilianEntity entity)
    {
        final ICitizenData data = citizens.get(entity.getCivilianID());
        if (data != null && data.getEntity().isPresent() && data.getEntity().get() == entity)
        {
            citizens.get(entity.getCivilianID()).setEntity(null);
        }
    }

    @Override
    public void read(@NotNull final CompoundTag compound)
    {
        citizens.forEach((id, citizen) -> citizen.getEntity().ifPresent(e -> e.remove(Entity.RemovalReason.DISCARDED)));
        citizens.clear();
        //  Citizens before Buildings, because Buildings track the Citizens
        citizens.putAll(NBTUtils.streamCompound(compound.getList(TAG_CITIZENS, Tag.TAG_COMPOUND))
                          .map(this::deserializeCitizen)
                          .collect(Collectors.toMap(ICitizenData::getId, Function.identity())));

        // Update child state after loading citizen data
        colony.updateHasChilds();
    }

    /**
     * Creates a citizen data from NBT
     *
     * @param compound NBT
     * @return citizen data
     */
    private ICitizenData deserializeCitizen(@NotNull final CompoundTag compound)
    {
        final ICitizenData data = ICitizenDataManager.getInstance().createFromNBT(compound, colony);
        topCitizenId = Math.max(topCitizenId, data.getId());
        return data;
    }

    @Override
    public void write(@NotNull final CompoundTag compoundNBT)
    {
        @NotNull final ListTag citizenTagList = citizens.values().stream().map(citizen -> citizen.serializeNBT()).collect(NBTUtils.toListNBT());
        compoundNBT.put(TAG_CITIZENS, citizenTagList);
    }

    @Override
    public void sendPackets(
      @NotNull final Set<ServerPlayer> closeSubscribers,
      @NotNull final Set<ServerPlayer> newSubscribers)
    {
        if (isCitizensDirty || !newSubscribers.isEmpty())
        {
            final Set<ServerPlayer> players = new HashSet<>();
            if (isCitizensDirty)
            {
                players.addAll(closeSubscribers);
            }
            players.addAll(newSubscribers);
            for (@NotNull final ICitizenData citizen : citizens.values())
            {
                if (citizen.isDirty() || !newSubscribers.isEmpty())
                {
                    final ColonyViewCitizenViewMessage message = new ColonyViewCitizenViewMessage(colony, citizen);
                    players.forEach(player -> Network.getNetwork().sendToPlayer(message, player));
                }
            }
        }
    }

    @Override
    public <T extends ICivilianData> T spawnOrCreateCivilian(final T data, final Level world, List<BlockPos> spawnPositions, final boolean force)
    {
        if (!colony.getSettings().getSetting(BuildingTownHall.MOVE_IN).getValue() && !force)
        {
            return data;
        }

        if (colony.getServerBuildingManager().hasTownHall() && spawnPositions.isEmpty())
        {
            spawnPositions = new ArrayList<>();
            spawnPositions.add(colony.getServerBuildingManager().getTownHall().getPosition());
        }

        for (final BlockPos spawnLocation : spawnPositions)
        {
            if (spawnLocation == null || spawnLocation.equals(BlockPos.ZERO))
            {
                continue;
            }

            if (WorldUtil.isEntityBlockLoaded(world, spawnLocation))
            {
                BlockPos calculatedSpawn = EntityUtils.getSpawnPoint(world, spawnLocation);
                if (calculatedSpawn != null)
                {
                    return (T) spawnCitizenOnPosition((ICitizenData) data, world, force, calculatedSpawn);
                }
                else if (colony.getServerBuildingManager().hasTownHall() && spawnLocation.equals(colony.getServerBuildingManager().getTownHall().getPosition()))
                {
                    final BlockPos townhallPos = colony.getServerBuildingManager().getTownHall().getPosition();
                    MessageUtils.format(WARNING_COLONY_NO_ARRIVAL_SPACE, townhallPos.getX(), townhallPos.getY(), townhallPos.getZ()).sendTo(colony).forAllPlayers();
                }
            }
        }

        return data;
    }

    @NotNull
    private ICitizenData spawnCitizenOnPosition(
      @Nullable final ICitizenData data,
      @NotNull final Level world,
      final boolean force,
      final BlockPos spawnPoint)
    {
        ICitizenData citizenData = data;
        if (citizenData == null)
        {
            citizenData = createAndRegisterCivilianData();

            if (getMaxCitizens() >= getCurrentCitizenCount() && !force)
            {
                if (maxCitizensFromResearch() <= getCurrentCitizenCount())
                {
                    MessageUtils.format(WARNING_MAX_CITIZENS_RESEARCH, colony.getName()).sendTo(colony).forAllPlayers();
                }
                else
                {
                    MessageUtils.format(WARNING_MAX_CITIZENS_CONFIG, colony.getName()).sendTo(colony).forAllPlayers();
                }
            }

            colony.getEventDescriptionManager().addEventDescription(new CitizenSpawnedEvent(spawnPoint, citizenData.getName()));
        }

        if (world instanceof ServerLevel serverLevel)
        {
            Entity existing = serverLevel.getEntity(citizenData.getUUID());
            if (existing != null)
            {
                existing.discard();
                existing = serverLevel.getEntity(citizenData.getUUID());
                if (existing != null)
                {
                    serverLevel.entityManager.stopTracking(existing);
                }
            }
        }

        final EntityCitizen entity = (EntityCitizen) ModEntities.CITIZEN.create(world);

        entity.setUUID(citizenData.getUUID());
        entity.setPos(spawnPoint.getX() + HALF_BLOCK, spawnPoint.getY() + SLIGHTLY_UP, spawnPoint.getZ() + HALF_BLOCK);

        entity.setCitizenId(citizenData.getId());
        entity.getCitizenColonyHandler().setColonyId(colony.getID());

        world.addFreshEntity(entity);
        if (entity.isAddedToWorld())
        {
            entity.getCitizenColonyHandler().registerWithColony(citizenData.getColony().getID(), citizenData.getId());
        }

        markDirty();
        return citizenData;
    }

    @Override
    public ICitizenData createAndRegisterCivilianData()
    {
        //This ensures that citizen IDs are getting reused.
        //That's needed to prevent bugs when calling IDs that are not used.
        for (int i = 1; i <= this.getCurrentCitizenCount() + 1; i++)
        {
            if (this.getCivilian(i) == null)
            {
                topCitizenId = i;
                break;
            }
        }

        final CitizenData citizenData = new CitizenData(topCitizenId, colony);
        citizenData.initForNewCivilian();
        citizens.put(citizenData.getId(), citizenData);

        return citizenData;
    }

    @Override
    public ICitizenData resurrectCivilianData(@NotNull final CompoundTag compoundNBT, final boolean resetId, @NotNull final Level world, final BlockPos spawnPos)
    {
        //This ensures that citizen IDs are getting reused.
        //That's needed to prevent bugs when calling IDs that are not used.
        for (int i = 1; i <= this.getCurrentCitizenCount() + 1; i++)
        {
            if (this.getCivilian(i) == null)
            {
                topCitizenId = i;
                break;
            }
        }

        if(resetId)
        {
            compoundNBT.putInt(TAG_ID, topCitizenId);
        }

        final ICitizenData citizenData = deserializeCitizen(compoundNBT);
        citizenData.onResurrect();
        citizens.put(citizenData.getId(), citizenData);
        spawnOrCreateCitizen(citizenData, world, spawnPos);

        IMinecoloniesAPI.getInstance().getEventBus().post(new CitizenAddedModEvent(citizenData, CitizenAddedModEvent.CitizenAddedSource.RESURRECTED));
        return citizenData;
    }

    @Override
    public void removeCivilian(@NotNull final ICivilianData citizen)
    {
        if (!(citizen instanceof ICitizenData))
        {
            return;
        }

        //Remove the Citizen
        citizens.remove(citizen.getId());

        for (@NotNull final IBuilding building : colony.getServerBuildingManager().getBuildings().values())
        {
            for (final AbstractAssignedCitizenModule assignedCitizenModule : building.getModulesByType(AbstractAssignedCitizenModule.class))
            {
                assignedCitizenModule.removeCitizen((ICitizenData) citizen);
            }
        }

        colony.getWorkManager().clearWorkForCitizen((ICitizenData) citizen);

        //  Inform Subscribers of removed citizen
        for (final ServerPlayer player : colony.getPackageManager().getCloseSubscribers())
        {
            Network.getNetwork().sendToPlayer(new ColonyViewRemoveCitizenMessage(colony, citizen.getId()), player);
        }

        calculateMaxCitizens();
        markDirty();
        colony.markDirty();
    }

    @Override
    public ICitizenData getJoblessCitizen()
    {
        for (@NotNull final ICitizenData citizen : citizens.values())
        {
            if (citizen.getWorkBuilding() == null && !citizen.isChild())
            {
                return citizen;
            }
        }

        return null;
    }

    @Override
    public void calculateMaxCitizens()
    {
        int newMaxCitizens = 0;
        int potentialMax = 0;

        for (final IBuilding b : colony.getServerBuildingManager().getBuildings().values())
        {
            if (b.getBuildingLevel() > 0)
            {
                if (b.hasModule(BuildingModules.BED) && b.hasModule(WorkAtHomeBuildingModule.class))
                {
                    final WorkAtHomeBuildingModule module = b.getFirstModuleOccurance(WorkAtHomeBuildingModule.class);
                    newMaxCitizens += b.getAllAssignedCitizen().size();
                    potentialMax += module.getModuleMax() - b.getAllAssignedCitizen().size();
                }
                else if (b.hasModule(LivingBuildingModule.class))
                {
                    final LivingBuildingModule module = b.getFirstModuleOccurance(LivingBuildingModule.class);
                    if (HiringMode.LOCKED.equals(module.getHiringMode()))
                    {
                        newMaxCitizens += module.getAssignedCitizen().size();
                    }
                    else
                    {
                        newMaxCitizens += module.getModuleMax();
                    }
                }
            }
        }
        if (getMaxCitizens() != newMaxCitizens || getPotentialMaxCitizens() != potentialMax + newMaxCitizens)
        {
            setMaxCitizens(newMaxCitizens);
            setPotentialMaxCitizens(potentialMax + newMaxCitizens);
            colony.markDirty();
        }
    }

    /**
     * Spawn a brand new Citizen.
     */
    public void spawnOrCreateCitizen()
    {
        spawnOrCreateCitizen(null, colony.getWorld(), null);
    }

    @NotNull
    @Override
    public Map<Integer, ICivilianData> getCivilianDataMap()
    {
        return Collections.unmodifiableMap(citizens);
    }

    @Override
    public void markDirty()
    {
        colony.markDirty();
        isCitizensDirty = true;
    }

    @Override
    public ICitizenData getCivilian(final int citizenId)
    {
        return citizens.get(citizenId);
    }

    @Override
    public void clearDirty()
    {
        isCitizensDirty = false;
        citizens.values().forEach(ICitizenData::clearDirty);
    }

    @Override
    public List<ICitizenData> getCitizens()
    {
        return new ArrayList<>(citizens.values());
    }

    @Override
    public int getMaxCitizens()
    {
        return (int) Math.max(1, Math.min(maxCitizens, Math.min(maxCitizensFromResearch(), MineColonies.getConfig().getServer().maxCitizenPerColony.get())));
    }

    @Override
    public int getPotentialMaxCitizens()
    {
        return (int) Math.max(1, Math.min(potentialMaxCitizens, Math.min(maxCitizensFromResearch(), MineColonies.getConfig().getServer().maxCitizenPerColony.get())));
    }

    @Override
    public double maxCitizensFromResearch()
    {
        if (MinecoloniesAPIProxy.getInstance().getGlobalResearchTree().hasResearchEffect(CITIZEN_CAP))
        {
            final int max = Math.max(CitizenConstants.CITIZEN_LIMIT_DEFAULT, (int) colony.getResearchManager().getResearchEffects().getEffectStrength(CITIZEN_CAP));
            return Math.min(max, MineColonies.getConfig().getServer().maxCitizenPerColony.get());
        }
        else
        {
            return MineColonies.getConfig().getServer().maxCitizenPerColony.get();
        }
    }

    /**
     * Get the current amount of citizens, might be bigger then {@link #getMaxCitizens()}
     *
     * @return The current amount of citizens in the colony.
     */
    @Override
    public int getCurrentCitizenCount()
    {
        return citizens.size();
    }

    @Override
    public void setMaxCitizens(final int newMaxCitizens)
    {
        this.maxCitizens = newMaxCitizens;
    }

    @Override
    public void setPotentialMaxCitizens(final int newPotentialMax)
    {
        this.potentialMaxCitizens = newPotentialMax;
    }

    @Override
    public void injectModifier(final IHappinessModifier modifier)
    {
        for (final ICitizenData citizenData : citizens.values())
        {
            citizenData.getCitizenHappinessHandler().addModifier(modifier);
        }
    }

    @Override
    public void checkCitizensForHappiness()
    {
        for (final ICitizenData citizenData : citizens.values())
        {
            citizenData.getCitizenHappinessHandler().processDailyHappiness(citizenData);
        }
    }

    @Override
    public boolean tickCitizenData(final int tickRate)
    {
        for (ICitizenData iCitizenData : this.getCitizens())
        {
            iCitizenData.update(tickRate);
        }
        return false;
    }

    /**
     * Updates the citizen entities when needed and spawn the initial citizens on colony tick.
     *
     * @param colony the colony being ticked.
     */
    @Override
    public void onColonyTick(final IColony colony)
    {
        if (colony.getServerBuildingManager().hasTownHall() && (citizenRespawnTimer -= 500) < 0)
        {
            citizenRespawnTimer = 5 * 60 * TICKS_SECOND;
            getCitizens().stream().filter(Objects::nonNull).forEach(ICitizenData::updateEntityIfNecessary);
        }

        //  Spawn initial Citizens
        if (colony.getSettings().getSetting(BuildingTownHall.MOVE_IN).getValue() && colony.getServerBuildingManager().hasTownHall() && getCitizens().size() < MineColonies.getConfig().getServer().initialCitizenAmount.get())
        {
            respawnInterval -= 500 + (SECONDS_A_MINUTE * colony.getServerBuildingManager().getTownHall().getBuildingLevel());

            if (respawnInterval <= 0)
            {
                respawnInterval = 60 * TICKS_SECOND;
                int femaleCount = 0;
                for (ICitizenData citizens : getCitizens())
                {
                    femaleCount += citizens.isFemale() ? 1 : 0;
                }

                final boolean firstCitizen = getCitizens().size() == 0;
                final ICitizenData newCitizen = createAndRegisterCivilianData();
                if (firstCitizen)
                {
                    colony.getQuestManager().injectAvailableQuest(new QuestInstance(new ResourceLocation(MOD_ID, "tutorial/welcome"), colony, List.of(new CitizenTriggerReturnData(newCitizen))));
                }

                // For first citizen, give a random chance of male or female.
                if (getCitizens().size() == 1)
                {
                    newCitizen.setGenderAndGenerateName(random.nextBoolean());
                }
                // Otherwise, set the new colonist's gender to whatever gender is less common.
                // Use double division to avoid getting two male colonists in a row for the first set.
                else if (femaleCount < (getCitizens().size() - 1) / 2.0)
                {
                    newCitizen.setGenderAndGenerateName(true);
                }
                else
                {
                    newCitizen.setGenderAndGenerateName(false);
                }

                spawnOrCreateCivilian(newCitizen, colony.getWorld(), List.of(colony.getServerBuildingManager().getTownHall().getPosition()), true);

                IMinecoloniesAPI.getInstance().getEventBus().post(new CitizenAddedModEvent(newCitizen, CitizenAddedModEvent.CitizenAddedSource.INITIAL));
                colony.getEventDescriptionManager().addEventDescription(new CitizenSpawnedEvent(colony.getServerBuildingManager().getTownHall().getPosition(),
                      newCitizen.getName()));
            }
        }
    }

    @Override
    public void updateCitizenMourn(final ICitizenData data, final boolean mourn)
    {
        for (final ICitizenData citizen : getCitizens())
        {
            if (mourn)
            {
                if (!(citizen.getJob() instanceof AbstractJobGuard) && !(citizen.getJob() instanceof JobUndertaker) && (citizen.isRelatedTo(data) || citizen.doesLiveWith(data)))
                {
                    citizen.getCitizenMournHandler().addDeceasedCitizen(data.getName());
                }
            }
            else
            {
                citizen.getCitizenMournHandler().removeDeceasedCitizen(data.getName());
            }
            citizen.onDeath(data.getId());
        }
    }

    @Override
    public ICitizenData getRandomCitizen()
    {
        return (ICitizenData) citizens.values().toArray()[random.nextInt(citizens.values().size())];
    }

    @Override
    public void updateCitizenSleep(final boolean sleep)
    {
        this.areCitizensSleeping = sleep;
    }

    @Override
    public void onCitizenSleep()
    {
        for (final ICitizenData citizenData : citizens.values())
        {
            if (!(citizenData.isAsleep() || citizenData.getJob() instanceof AbstractJobGuard))
            {
                return;
            }
        }

        if (!this.areCitizensSleeping)
        {
            MessageUtils.format(ALL_CITIZENS_ARE_SLEEPING).sendTo(colony).forAllPlayers();
        }

        this.areCitizensSleeping = true;
    }

    @Override
    public void onWakeUp()
    {
        for (final ICitizenData citizenData : citizens.values())
        {
            citizenData.updateEntityIfNecessary();
            if (citizenData.getCitizenMournHandler().isMourning())
            {
                citizenData.getCitizenMournHandler().clearDeceasedCitizen();
                citizenData.getCitizenMournHandler().setMourning(false);
            }
            else
            {
                if (citizenData.getCitizenMournHandler().shouldMourn())
                {
                    citizenData.getCitizenMournHandler().setMourning(true);
                }
            }
        }
    }

    @Override
    public void afterBuildingLoad()
    {
        calculateMaxCitizens();

        for(final ICitizenData data: citizens.values())
        {
            data.onBuildingLoad();
        }
    }

    @Override
    public void onFlagChange()
    {
        for (ICitizenData citizen : this.getCitizens())
        {
            if (citizen.getEntity().isPresent() && citizen.getJob() instanceof IJobWithColonyFlag flagUser)
            {
                flagUser.onColonyFlagChanged();
            }
        }
    }
}

package com.minecolonies.core.colony.managers;

import com.ldtteam.structurize.util.BlockUtils;
import com.minecolonies.api.blocks.ModBlocks;
import com.minecolonies.api.colony.GraveData;
import com.minecolonies.api.colony.ICitizenData;
import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.colony.managers.interfaces.IGraveManager;
import com.minecolonies.api.util.BlockPosUtil;
import com.minecolonies.api.util.InventoryUtils;
import com.minecolonies.api.util.MessageUtils;
import com.minecolonies.api.util.WorldUtil;
import com.minecolonies.core.blocks.BlockMinecoloniesGrave;
import com.minecolonies.core.colony.Colony;
import com.minecolonies.core.tileentities.TileEntityGrave;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.AirBlock;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import org.jetbrains.annotations.NotNull;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

import static com.minecolonies.api.entity.ai.statemachine.tickratestatemachine.TickRateConstants.MAX_TICKRATE;
import static com.minecolonies.api.research.util.ResearchConstants.GRAVE_DECAY_BONUS;
import static com.minecolonies.api.util.constant.NbtTagConstants.*;
import static com.minecolonies.api.util.constant.TranslationConstants.WARNING_GRAVE_LAVA;
import static com.minecolonies.api.util.constant.TranslationConstants.WARNING_GRAVE_WATER;

public class GraveManager implements IGraveManager
{
    /**
     * List of grave in the colony.
     */
    @NotNull
    private final Map<BlockPos, Boolean> graves = new HashMap<>();

    /**
     * The colony of the manager.
     */
    private final Colony colony;

    /**
     * Creates the GraveManager for a colony.
     *
     * @param colony the colony.
     */
    public GraveManager(final Colony colony)
    {
        this.colony = colony;
    }

    /**
     * Read the graves from NBT.
     *
     * @param compound the compound.
     */
    @Override
    public void read(@NotNull final CompoundTag compound)
    {
        graves.clear();
        final ListTag gravesTagList = compound.getList(TAG_GRAVE, Tag.TAG_COMPOUND);
        for (int i = 0; i < gravesTagList.size(); ++i)
        {
            final CompoundTag graveCompound = gravesTagList.getCompound(i);
            if (graveCompound.contains(TAG_POS) && graveCompound.contains(TAG_RESERVED))
            {
                graves.put(BlockPosUtil.read(graveCompound, TAG_POS), graveCompound.getBoolean(TAG_RESERVED));
            }
        }
    }

    /**
     * Write the graves to NBT.
     *
     * @param compound the compound.
     */
    @Override
    public void write(@NotNull final CompoundTag compound)
    {
        @NotNull final ListTag gravesTagList = new ListTag();
        for (@NotNull final BlockPos blockPos : graves.keySet())
        {
            @NotNull final CompoundTag graveCompound = new CompoundTag();
            BlockPosUtil.write(graveCompound, TAG_POS, blockPos);
            graveCompound.putBoolean(TAG_RESERVED, graves.get(blockPos));
            gravesTagList.add(graveCompound);
        }
        compound.put(TAG_GRAVE, gravesTagList);
    }

    /**
     * Ticks all grave when this building manager receives a tick.
     *
     * @param colony the colony which is being ticked.
     */
    @Override
    public void onColonyTick(final IColony colony)
    {
        for (final Iterator<BlockPos> iterator = graves.keySet().iterator(); iterator.hasNext(); )
        {
            final BlockPos pos = iterator.next();
            if (!WorldUtil.isBlockLoaded(colony.getWorld(), pos))
            {
                continue;
            }

            final BlockEntity graveEntity = colony.getWorld().getBlockEntity(pos);
            if (!(graveEntity instanceof TileEntityGrave))
            {
                iterator.remove();
                colony.markDirty();
                continue;
            }

            if (!((TileEntityGrave) graveEntity).onColonyTick(MAX_TICKRATE))
            {
                iterator.remove();
                colony.markDirty();
            }
        }
    }

    /**
     * Returns a map with all graves within the colony. Key is ID (Coordinates), value is isReserved boolean.
     *
     * @return Map with ID (coordinates) as key, value is isReserved boolean.
     */
    @NotNull
    @Override
    public Map<BlockPos, Boolean> getGraves()
    {
        return graves;
    }

    /**
     * Add a grave from the Colony.
     *
     * @param pos position of the TileEntityGrave to add.
     * @return the grave that was created and added.
     */
    @Override
    public boolean addNewGrave(@NotNull final BlockPos pos)
    {
        final TileEntityGrave graveEntity = (TileEntityGrave) colony.getWorld().getBlockEntity(pos);
        if (graveEntity == null)
        {
            return false;
        }

        if (graves.containsKey(pos))
        {
            return true;
        }

        graves.put(pos, false);
        colony.markDirty();
        return true;
    }

    /**
     * Remove a TileEntityGrave from the Colony (when it is destroyed).
     *
     * @param pos position of the TileEntityGrave to remove.
     */
    @Override
    public void removeGrave(@NotNull final BlockPos pos)
    {
        graves.remove(pos);
        colony.markDirty();
    }

    /**
     * Reserve a grave
     *
     * @param pos the id of the grave.
     * @return is the grave successfully reserved.
     */
    @Override
    public boolean reserveGrave(@NotNull final BlockPos pos)
    {
        if (!graves.containsKey(pos) || graves.get(pos))
        {
            return false;
        }

        graves.put(pos, true);
        colony.markDirty();
        return true;
    }

    @Override
    public void unReserveGrave(@NotNull final BlockPos pos)
    {
        if (graves.containsKey(pos) && graves.get(pos))
        {
            graves.put(pos, false);
            colony.markDirty();
        }
    }

    /**
     * Reserve the next free grave
     *
     * @return the grave successfully reserved or null if none available
     */
    @Override
    public BlockPos reserveNextFreeGrave()
    {
        for (@NotNull final BlockPos pos : new ArrayList<>(graves.keySet()))
        {
            if (!WorldUtil.isBlockLoaded(colony.getWorld(), pos))
            {
                continue;
            }

            final BlockEntity graveEntity = colony.getWorld().getBlockEntity(pos);
            if (!(graveEntity instanceof TileEntityGrave))
            {
                graves.remove(pos);
                continue;
            }

            if (reserveGrave(pos))
            {
                return pos;
            }
        }

        return null;
    }

    /**
     * Attempt to create a TileEntityGrave at @pos containing the specific @citizenData
     * <p>
     * On failure: drop all the citizen inventory on the ground.
     *
     * @param world       The world.
     * @param pos         The position where to spawn a grave
     * @param citizenData The citizenData
     */
    @Override
    public BlockPos createCitizenGrave(final Level world, final BlockPos pos, final ICitizenData citizenData)
    {
        final BlockState here = world.getBlockState(pos);
        if (here.getBlock() == Blocks.LAVA)
        {
            MessageUtils.format(WARNING_GRAVE_LAVA).sendTo(colony).forManagers();
            return null;
        }

        BlockPos firstValidPosition = null;
        if (here.getBlock() == Blocks.WATER)
        {
            for (int i = 1; i <= 10; i++)
            {
                if (world.getBlockState(pos.above(i)).getBlock() instanceof AirBlock)
                {
                    firstValidPosition = BlockPosUtil.findAround(world, pos, 1, 16,
                      (blockAccess, current) ->
                        blockAccess.getBlockState(current).isAir() &&
                          BlockUtils.isAnySolid(blockAccess.getBlockState(current.below())));
                    break;
                }
            }

            if (firstValidPosition == null)
            {
                MessageUtils.format(WARNING_GRAVE_WATER).sendTo(colony).forManagers();
            }
        }
        else
        {
            firstValidPosition = BlockPosUtil.findAround(world, pos, 10, 10,
              (blockAccess, current) ->
                blockAccess.getBlockState(current).isAir() &&
                  BlockUtils.isAnySolid(blockAccess.getBlockState(current.below())));
        }


        if (firstValidPosition != null)
        {
            world.setBlockAndUpdate(firstValidPosition,
              BlockMinecoloniesGrave.getPlacementState(ModBlocks.blockGrave.defaultBlockState(), firstValidPosition));
            final TileEntityGrave graveEntity = (TileEntityGrave) world.getBlockEntity(firstValidPosition);
            if (!InventoryUtils.transferAllItemHandler(citizenData.getInventory(), graveEntity.getInventory()))
            {
                InventoryUtils.dropItemHandler(citizenData.getInventory(), world, pos.getX(), pos.getY(), pos.getZ());
            }
            for (final EquipmentSlot equipmentSlot : EquipmentSlot.values())
            {
                final ItemStack stack = citizenData.getInventory().getArmorInSlot(equipmentSlot);
                if (!InventoryUtils.addItemStackToItemHandler(graveEntity.getInventory(), stack))
                {
                    InventoryUtils.spawnItemStack(world, pos.getX(), pos.getY(), pos.getZ(), stack);
                }
            }


            graveEntity.delayDecayTimer(colony.getResearchManager().getResearchEffects().getEffectStrength(GRAVE_DECAY_BONUS));

            GraveData graveData = new GraveData();
            graveData.setCitizenName(citizenData.getName());
            if (citizenData.getJob() != null)
            {
                final Component jobName = Component.translatable(citizenData.getJob().getJobRegistryEntry().getTranslationKey().toLowerCase());
                graveData.setCitizenJobName(jobName.getString());
            }
            graveData.setCitizenDataNBT(citizenData.serializeNBT());
            graveEntity.setGraveData(graveData);

            addNewGrave(firstValidPosition);
            return firstValidPosition;
        }
        else
        {
            InventoryUtils.dropItemHandler(citizenData.getInventory(), world, pos.getX(), pos.getY(), pos.getZ());
        }
        return null;
    }
}

package com.minecolonies.core.colony.managers;

import com.minecolonies.api.colony.managers.interfaces.IStatisticsManager;
import it.unimi.dsi.fastutil.ints.Int2IntLinkedOpenHashMap;
import it.unimi.dsi.fastutil.ints.Int2IntMap;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.FriendlyByteBuf;
import org.jetbrains.annotations.NotNull;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import static com.minecolonies.api.util.constant.NbtTagConstants.*;

/**
 * Manager for colony related statistics.
 */
public class StatisticsManager implements IStatisticsManager
{
    /**
     * NBT tags.
     */
    private static final String TAG_STAT_MANAGER = "stat_manager";
    private static final String TAG_STAT         = "stat";

    /**
     * The current stats of the colony.
     */
    private final Map<String, Int2IntLinkedOpenHashMap> stats = new HashMap<>();

    /**
     * The modified and not yet sent stats
     */
    private Set<String> dirtyStats = new HashSet<>();

    @Override
    public void increment(final @NotNull String id, final int day)
    {
        incrementBy(id, 1, day);
    }

    @Override
    public void incrementBy(final @NotNull String id, int qty, final int day)
    {
        final Int2IntLinkedOpenHashMap innerMap = stats.computeIfAbsent(id, k -> new Int2IntLinkedOpenHashMap());
        innerMap.addTo(day, qty);
        dirtyStats.add(id);
    }

    @Override
    public int getStatTotal(final @NotNull String id)
    {
        final Int2IntLinkedOpenHashMap stats = this.stats.getOrDefault(id, new Int2IntLinkedOpenHashMap());
        int totalCount = 0;
        for (final int count : stats.values())
        {
            totalCount += count;
        }
        return totalCount;
    }

    @Override
    public int getStatsInPeriod(final @NotNull String id, final int startDay, final int endDay)
    {
        final Int2IntLinkedOpenHashMap stats = this.stats.getOrDefault(id, new Int2IntLinkedOpenHashMap());
        int count = 0;
        for (int day = startDay; day <= endDay; day++)
        {
            count += stats.get(day);
        }
        return count;
    }

    @Override
    public @NotNull Set<String> getStatTypes()
    {
        return stats.keySet();
    }

    /**
     * Gets all the current stat entries in this manager.
     * @return a set of entries with the id and the stats map.
     */
    @Override
    public @NotNull Set<Map.Entry<String, Int2IntLinkedOpenHashMap>>  getStatEntries()
    {
        return stats.entrySet();
    }

    /**
     * Clear all the statistics, this will remove all the entries from the map
     */
    @Override
    public void clear()
    {
        dirtyStats.addAll(stats.keySet());
        stats.clear();
    }

    @Override
    public void serialize(@NotNull final FriendlyByteBuf buf, final boolean fullSync)
    {
        buf.writeBoolean(fullSync);
        buf.writeVarInt(fullSync ? stats.size() : dirtyStats.size());

        if (fullSync)
        {
            for (final Map.Entry<String, Int2IntLinkedOpenHashMap> dataEntry : stats.entrySet())
            {
                buf.writeUtf(dataEntry.getKey());
                buf.writeVarInt(dataEntry.getValue().size());

                for (final Int2IntMap.Entry valueEntry : dataEntry.getValue().int2IntEntrySet())
                {
                    buf.writeVarInt(valueEntry.getIntKey());
                    buf.writeVarInt(valueEntry.getIntValue());
                }
            }
        }
        else
        {
            for (final String id : dirtyStats)
            {
                final Int2IntLinkedOpenHashMap dataEntry = stats.get(id);

                buf.writeUtf(id);
                if (dataEntry == null)
                {
                    buf.writeVarInt(0);
                    continue;
                }

                buf.writeVarInt(1);
                buf.writeVarInt(dataEntry.lastIntKey());
                buf.writeVarInt(dataEntry.get(dataEntry.lastIntKey()));
            }
        }

        if (!dirtyStats.isEmpty())
        {
            dirtyStats = new HashSet<>();
        }
    }

    @Override
    public void deserialize(@NotNull final FriendlyByteBuf buf)
    {
        final boolean fullSync = buf.readBoolean();
        if (fullSync)
        {
            stats.clear();
        }

        final int statSize = buf.readVarInt();
        for (int i = 0; i < statSize; i++)
        {
            final String id = buf.readUtf();
            final int statEntrySize = buf.readVarInt();

            if (!fullSync && statEntrySize == 0)
            {
                stats.remove(id);
                continue;
            }

            final Int2IntLinkedOpenHashMap statValues = (fullSync || !stats.containsKey(id)) ? new Int2IntLinkedOpenHashMap(statEntrySize) : stats.get(id);
            for (int j = 0; j < statEntrySize; j++)
            {
                statValues.put(buf.readVarInt(), buf.readVarInt());
            }

            stats.put(id, statValues);
        }
    }

    @Override
    public void writeToNBT(@NotNull final CompoundTag compound)
    {
        final ListTag statManagerNBT = new ListTag();
        for (final Map.Entry<String, Int2IntLinkedOpenHashMap> stat : stats.entrySet())
        {
            final CompoundTag statCompound = new CompoundTag();
            statCompound.putString(TAG_ID, stat.getKey());

            final ListTag statNBT = new ListTag();
            for (final Map.Entry<Integer, Integer> dailyStats : stat.getValue().entrySet())
            {
                final CompoundTag timeStampTag = new CompoundTag();

                timeStampTag.putInt(TAG_TIME, dailyStats.getKey());
                timeStampTag.putInt(TAG_QUANTITY, dailyStats.getValue());

                statNBT.add(timeStampTag);
            }

            statCompound.put(TAG_STAT, statNBT);
            statManagerNBT.add(statCompound);
        }

        compound.put(TAG_STAT_MANAGER, statManagerNBT);
    }

    @Override
    public void readFromNBT(@NotNull final CompoundTag compound)
    {
        stats.clear();
        if (compound.contains(TAG_STAT_MANAGER))
        {
            final ListTag statsNbts = compound.getList(TAG_STAT_MANAGER, Tag.TAG_COMPOUND);
            for (int i = 0; i < statsNbts.size(); i++)
            {
                final CompoundTag statCompound = statsNbts.getCompound(i);
                final String id = statCompound.getString(TAG_ID);
                final ListTag timeStampNbts = statCompound.getList(TAG_STAT, Tag.TAG_COMPOUND);
                final Int2IntLinkedOpenHashMap timeStamps = new Int2IntLinkedOpenHashMap();
                for (int j = 0; j < timeStampNbts.size(); j++)
                {
                    final CompoundTag compoundTag = timeStampNbts.getCompound(j);
                    final int day = compoundTag.getInt(TAG_TIME);
                    final int qty = compoundTag.getInt(TAG_QUANTITY);

                    timeStamps.put(day, qty);
                }

                stats.put(id, timeStamps);
            }
        }
    }
}

